class Solution:
    def maxPerformance(self, n: int, speed: list[int], efficiency: list[int], k: int) -> int:
        mod = 1000000007
        best = 0
        for e in efficiency:
            eligible = [speed[i] for i in range(n) if efficiency[i] >= e]
            eligible.sort(reverse=True)
            best = max(best, sum(eligible[:k]) * e)
        return best % mod

